int main() {
    int N, K;
    scanf("%d %d", &N, &K);
    int a[N];
    for (int i = 0; i < N; i++) scanf("%d", &a[i]);

    // For each operation: probability that a given pair (i,j) is chosen
    // Probability = (number of subsequences containing both) / (total subsequences)
    // total subsequences = 2^N
    // containing both i,j = 2^(N-2)
    // So probability for one operation = 1/4
    long long p_single = (MOD + 1) / 4; // modular inverse of 4

    // After K operations, probability of odd number of reversals:
    // Let p = 1/4 = probability of reversal in one operation.
    // After K ops, prob(reversal odd) = (1 - (1-2p)^K)/2
    // 1 - 2p = 1 - 2*(1/4) = 1 - 1/2 = 1/2
    // So prob = (1 - (1/2)^K)/2

    long long half = (MOD + 1) / 2; // modular inverse of 2
    long long pow_half_K = modpow(half, K);
    long long prob_rev = (1 - pow_half_K + MOD) % MOD * half % MOD;

    long long ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (a[i] > a[j]) {
                // originally inverted, will become non-inverted with prob_rev
                ans = (ans + (1 - prob_rev + MOD) % MOD) % MOD;
            } else {
                // originally not inverted, becomes inverted with prob_rev
                ans = (ans + prob_rev) % MOD;
            }
        }
    }
    printf("%lld\n", ans);
    return 0;
}

