int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    int a[200005];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    // Count far inversions (j - i >= k)
    long long far_inv = 0;
    // Use BIT for counting inversions with gap >= k
    // For each j, count i < j with j-i >= k and a[i] > a[j]
    // i.e., i <= j-k

    long long bit[200005] = {0};

    // BIT operations
    // We'll process j from 0 to n-1
    // For each j, query how many a[i] > a[j] for i <= j-k
    // Add a[j-k+... wait, we add a[i] to BIT when i = j-k

    // Actually: for each j, we want count of i in [0, j-k] with a[i] > a[j]
    // So we insert a[i] into BIT when j reaches i+k

    for (int j = 0; j < n; j++) {
        int threshold = j - k; // i <= threshold
        if (threshold >= 0) {
            // insert a[threshold] into BIT
            int v = a[threshold];
            for (int x = v; x <= n; x += x & (-x)) bit[x]++;
        }
        // query: how many inserted values > a[j]
        // = inserted_count - count(values <= a[j])
        long long leq = 0;
        for (int x = a[j]; x > 0; x -= x & (-x)) leq += bit[x];
        long long inserted = (threshold >= 0) ? threshold + 1 : 0;
        far_inv += inserted - leq;
    }

    long long close_pairs = 0;
    for (int d = 1; d < k && d < n; d++) close_pairs += (n - d);
    close_pairs %= MOD;

    long long inv2 = power(2, MOD - 2, MOD);
    long long ans = (close_pairs % MOD * inv2 % MOD + far_inv % MOD) % MOD;
    printf("%lld\n", ans);
    return 0;
}

