#define MOD 998244353LL

typedef long long ll;

static ll mod_pow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

static ll mod_inv(ll x) {
    return mod_pow(x, MOD - 2);
}

typedef struct {
    int l, r;
} Op;

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *a = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &a[i]);

    Op *ops = (Op*)malloc(K * sizeof(Op));
    for (int i = 0; i < K; i++) {
        scanf("%d %d", &ops[i].l, &ops[i].r);
    }

    ll inv2 = (MOD + 1) / 2;

    /* prob[x][y] = probability that value at position x is greater than value at position y]
       after processing operations so far. */
    ll *prob = (ll*)malloc((N + 1) * (N + 1) * sizeof(ll));
    #define P(i,j) prob[(ll)(i) * (N + 1) + (j)]

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            if (i == j) P(i,j) = 0;
            else P(i,j) = (a[i] > a[j]) ? 1 : 0;
        }
    }

    for (int t = 0; t < K; t++) {
        int l = ops[t].l, r = ops[t].r;
        int len = r - l + 1;
        ll inv_len = mod_inv(len);
        ll inv_len2 = inv_len * inv_len % MOD;

        /* Save old block-block values */
        ll *old = (ll*)malloc((ll)len * len * sizeof(ll));
        #define OLD(i,j) old[((i) - l) * len + ((j) - l)]
        for (int i = l; i <= r; i++) {
            for (int j = l; j <= r; j++) {
                OLD(i,j) = P(i,j);
            }
        }

        /* Update inside block:
           pick two positions uniformly from the block after random permutation.
           For i != j, probability is average over ordered pairs of distinct original positions. */
        ll sumDistinct = 0;
        for (int x = l; x <= r; x++) {
            for (int y = l; y <= r; y++) {
                if (x != y) {
                    sumDistinct += OLD(x,y);
                    if (sumDistinct >= MOD) sumDistinct -= MOD;
                }
            }
        }

        ll insideVal = sumDistinct * mod_inv((ll)len * (len - 1) % MOD) % MOD;
        for (int i = l; i <= r; i++) {
            for (int j = l; j <= r; j++) {
                if (i == j) P(i,j) = 0;
                else P(i,j) = insideVal;
            }
        }

        /* Update cross block probabilities */
        ll *rowAvg = (ll*)malloc((N + 1) * sizeof(ll));
        ll *colAvg = (ll*)malloc((N + 1) * sizeof(ll));

        for (int x = 1; x <= N; x++) rowAvg[x] = colAvg[x] = 0;

        for (int x = 1; x <= N; x++) {
            if (l <= x && x <= r) continue;

            ll s1 = 0, s2 = 0;
            for (int y = l; y <= r; y++) {
                s1 += P(x,y);
                if (s1 >= MOD) s1 -= MOD;
                s2 += P(y,x);
                if (s2 >= MOD) s2 -= MOD;
            }
            rowAvg[x] = s1 * inv_len % MOD;
            colAvg[x] = s2 * inv_len % MOD;
        }

        for (int x = 1; x <= N; x++) {
            if (l <= x && x <= r) continue;
            for (int y = l; y <= r; y++) {
                P(x,y) = rowAvg[x];
                P(y,x) = colAvg[x];
            }
        }

        free(old);
        free(rowAvg);
        free(colAvg);
    }

    ll ans = 0;
    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            ans += P(i,j);
            if (ans >= MOD) ans -= MOD;
        }
    }

    printf("%lld\n", ans % MOD);

    free(prob);
    free(ops);
    free(a);
    return 0;
}

