        for (int i = 0; i < N; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        // last operation index that included each position
        int[] lastOp = new int[N];
        Arrays.fill(lastOp, -1);

        for (int op = 0; op < K; op++) {
            st = new StringTokenizer(br.readLine());
            int L = Integer.parseInt(st.nextToken()) - 1;
            int R = Integer.parseInt(st.nextToken()) - 1;
            // Mark all positions in range with current operation index
            for (int i = L; i <= R; i++) {
                lastOp[i] = op;
            }
        }

        long invCount = 0;
        long inv2 = (MOD + 1) / 2; // modular inverse of 2

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (lastOp[i] != -1 && lastOp[i] == lastOp[j]) {
                    // They were together in the same last operation -> random order
                    // Probability inversion = 1/2
                    invCount = (invCount + inv2) % MOD;
                } else if (a[i] > a[j]) {
                    // They were never randomized together, keep original inversion
                    invCount = (invCount + 1) % MOD;
                }
                // else: not an inversion originally and not randomized => 0
            }
        }

        System.out.println(invCount);
    }
}

