        // Add all elements with index >= K
        for(int j=K;j<n;j++) update(a[j],1);
        long farInv=0;
        for(int i=0;i<n;i++){
            if(i+K<=n){ // there exist j>=i+K
                // count a[j]<a[i]: query(a[i]-1)
                farInv+=query(a[i]-1);
            }
            // remove a[i+K] from BIT (it's no longer >= i+1+K)
            if(i+K<n) update(a[i+K],-1);
        }
        long nearPairs=0;
        for(int d=1;d<=K-1&&d<n;d++) nearPairs+=(n-d);
        nearPairs%=MOD;
        long inv2=(MOD+1)/2; // since MOD is odd prime, inv2=(MOD+1)/2
        long ans=(nearPairs%MOD*inv2%MOD + farInv%MOD)%MOD;
        System.out.println(ans);
    }
}

