public class Main {
    static final long MOD = 998244353L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int K = fs.nextInt();

        int[] p = new int[N + 1];
        for (int i = 1; i <= N; i++) p[i] = fs.nextInt();

        // Probability that pair (i,j) is currently inverted.
        long[][] dp = new long[N + 1][N + 1];
        for (int i = 1; i <= N; i++) {
            for (int j = i + 1; j <= N; j++) {
                dp[i][j] = (p[i] > p[j]) ? 1 : 0;
            }
        }

        for (int op = 0; op < K; op++) {
            int l = fs.nextInt();
            int r = fs.nextInt();
            int len = r - l + 1;
            long inv2 = modPow(2, MOD - 2);

            // After shuffling uniformly inside [l, r]:
            // any pair fully inside gets inversion probability 1/2.
            for (int i = l; i <= r; i++) {
                for (int j = i + 1; j <= r; j++) {
                    dp[i][j] = inv2;
                }
            }

            // For outside-inside pairs, the inside index becomes uniformly any value in [l, r].
            long[] avgLeft = new long[l];
            for (int i = 1; i < l; i++) {
                long sum = 0;
                for (int j = l; j <= r; j++) sum += dp[i][j];
                avgLeft[i] = sum % MOD * modPow(len, MOD - 2) % MOD;
            }
            for (int i = 1; i < l; i++) {
                for (int j = l; j <= r; j++) dp[i][j] = avgLeft[i];
            }

            long[] avgRight = new long[N + 1];
            for (int j = r + 1; j <= N; j++) {
                long sum = 0;
                for (int i = l; i <= r; i++) sum += dp[i][j];
                avgRight[j] = sum % MOD * modPow(len, MOD - 2) % MOD;
            }
            for (int i = l; i <= r; i++) {
                for (int j = r + 1; j <= N; j++) dp[i][j] = avgRight[j];
            }
        }

        long ans = 0;
        for (int i = 1; i <= N; i++) {
            for (int j = i + 1; j <= N; j++) {
                ans += dp[i][j];
                if (ans >= MOD) ans -= MOD;
            }
        }

        System.out.println(ans % MOD);
    }
}

